create type public.price_status as enum ('cost_pending', 'approved', 'applied', 'ignored');

create table public.workspaces (id uuid primary key default gen_random_uuid(), name text not null, created_at timestamptz not null default now());
create table public.workspace_members (workspace_id uuid references public.workspaces(id) on delete cascade, user_id uuid references auth.users(id) on delete cascade, role text not null default 'editor' check (role in ('admin','editor','viewer')), primary key (workspace_id, user_id));
create table public.pricing_settings (workspace_id uuid primary key references public.workspaces(id) on delete cascade, target_margin_pct numeric not null default 35, target_markup_pct numeric not null default 55, min_margin_pct numeric not null default 25, updated_at timestamptz not null default now());
create table public.products (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, sku text not null, name text not null, category text, brand text, supplier text, current_cost_pence integer not null, new_cost_pence integer not null, selling_price_pence integer not null, proposed_selling_price_pence integer, target_margin_pct numeric, min_margin_pct numeric, status public.price_status not null default 'cost_pending', magento_product_id bigint, magento_product_type text, magento_payload jsonb, updated_at timestamptz not null default now(), unique(workspace_id, sku));
create table public.product_custom_options (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id) on delete cascade, magento_option_id bigint not null, title text not null, input_type text not null, is_required boolean not null default false, sort_order integer not null default 0, option_values jsonb not null default '[]', updated_at timestamptz not null default now(), unique(product_id, magento_option_id));
create table public.magento_connections (workspace_id uuid primary key references public.workspaces(id) on delete cascade, base_url text not null, store_code text not null default 'default', encrypted_access_token text not null, encryption_iv text not null, encryption_tag text not null, updated_by uuid references auth.users(id), updated_at timestamptz not null default now());
create table public.import_batches (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, filename text not null, source_type text not null default 'csv', matched_rows integer not null default 0, unmatched_rows integer not null default 0, created_by uuid references auth.users(id), created_at timestamptz not null default now());
create table public.audit_log (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, action text not null, subject_type text not null, subject_id uuid, payload jsonb not null default '{}', created_by uuid references auth.users(id), created_at timestamptz not null default now());
create table public.workspace_ai_settings (workspace_id uuid primary key references public.workspaces(id) on delete cascade, provider text not null default 'OpenAI', model text not null default 'gpt-4.1-mini', encrypted_api_key bytea not null, encryption_iv bytea not null, updated_by uuid references auth.users(id), updated_at timestamptz not null default now());
alter table public.workspaces enable row level security; alter table public.workspace_members enable row level security; alter table public.pricing_settings enable row level security; alter table public.products enable row level security; alter table public.product_custom_options enable row level security; alter table public.magento_connections enable row level security; alter table public.import_batches enable row level security; alter table public.audit_log enable row level security;
alter table public.workspace_ai_settings enable row level security;
create function public.is_workspace_member(target_workspace uuid) returns boolean language sql stable security definer set search_path = public as $$ select exists (select 1 from public.workspace_members where workspace_id = target_workspace and user_id = auth.uid()) $$;
create function public.can_edit_workspace(target_workspace uuid) returns boolean language sql stable security definer set search_path = public as $$ select exists (select 1 from public.workspace_members where workspace_id = target_workspace and user_id = auth.uid() and role in ('admin', 'editor')) $$;
create policy "members can read workspaces" on public.workspaces for select using (public.is_workspace_member(id));
create policy "members can read memberships" on public.workspace_members for select using (user_id = auth.uid() or public.is_workspace_member(workspace_id));
create policy "members can read settings" on public.pricing_settings for select using (public.is_workspace_member(workspace_id));
create policy "editors can update settings" on public.pricing_settings for update using (public.can_edit_workspace(workspace_id));
create policy "members can access products" on public.products for select using (public.is_workspace_member(workspace_id));
create policy "editors can create products" on public.products for insert with check (public.can_edit_workspace(workspace_id));
create policy "editors can change products" on public.products for update using (public.can_edit_workspace(workspace_id));
create policy "members can read product options" on public.product_custom_options for select using (exists (select 1 from public.products p where p.id = product_id and public.is_workspace_member(p.workspace_id)));
create policy "editors can manage product options" on public.product_custom_options for all using (exists (select 1 from public.products p where p.id = product_id and public.can_edit_workspace(p.workspace_id))) with check (exists (select 1 from public.products p where p.id = product_id and public.can_edit_workspace(p.workspace_id)));
create policy "admins can manage Magento connections" on public.magento_connections for all using (public.can_edit_workspace(workspace_id)) with check (public.can_edit_workspace(workspace_id));
create policy "members can read import batches" on public.import_batches for select using (public.is_workspace_member(workspace_id));
create policy "editors can create import batches" on public.import_batches for insert with check (public.can_edit_workspace(workspace_id));
create policy "members can read audit log" on public.audit_log for select using (public.is_workspace_member(workspace_id));
create policy "editors can create audit entries" on public.audit_log for insert with check (public.can_edit_workspace(workspace_id));
create policy "editors can manage AI settings" on public.workspace_ai_settings for all using (public.can_edit_workspace(workspace_id)) with check (public.can_edit_workspace(workspace_id));
